export const FREE_LESSONS=[
  {id:'nclex-plan',track:'nclex',title:'Build a revision map',minutes:6,summary:'Turn a broad examination goal into a specific next study session.',sources:['nclex'],sections:[
    {title:'Start with the right map',text:'Use the current official test plan to organise revision. The NCLEX-RN framework uses Client Needs categories; a social-media topic list is not a substitute for the official outline. This starter activity is a planning aid, not complete blueprint coverage.'},
    {title:'Make the goal small enough to start',text:'Choose one topic from your course materials. Write what you want to be able to explain, choose the resource you will use, and set a manageable session length. “Explain this idea in my own words” gives you something clearer to review than “study nursing”.'},
    {title:'Finish with evidence',text:'Close the resource and write a short explanation from memory. Check it against the material. Record the point that needs another look, then schedule that return in your planner.'}
  ],activity:'Create one planner task: name the topic, set a date, and write the question you want to answer. After studying, add one sentence explaining what changed in your understanding.'},
  {id:'nclex-hygiene',track:'nclex',title:'Recognise hand-hygiene opportunities',minutes:5,summary:'Connect the five-moments framework with the sequence of care.',sources:['hygiene'],sections:[
    {title:'Notice the transitions',text:'WHO identifies opportunities ahead of patient contact and aseptic work, and following exposure risk, patient contact, or handling the surrounding care area. Think about the transition between activities rather than waiting for a vague “end of care”.'},
    {title:'Use a neutral example',text:'Imagine a learner finishes arranging items around a patient, then prepares for a new task. Which transition needs attention? Naming the moment helps you connect a framework to a sequence rather than memorise a number.'},
    {title:'Know the boundary',text:'This is a recognition exercise. Use your approved training and local infection-prevention procedures for technique, product selection, protective equipment, and clinical care.'}
  ],activity:'Without looking, describe the two “before” opportunities and the three “after” opportunities. Open the WHO source, check your list, and note the one you initially missed.'},
  {id:'nclex-errors',track:'nclex',title:'Make an error useful',minutes:5,summary:'Turn an incorrect answer into a specific revision action.',sources:[],sections:[
    {title:'Separate the result from the reason',text:'An incorrect answer tells you where to look next. It does not, on its own, explain the cause. Ask whether you missed a key word, did not know a concept, or applied a rule in the wrong context.'},
    {title:'Write a compact error log',text:'Use four headings: the topic, what I thought, what changed after review, and my next action. Avoid copying an entire rationale. A short explanation in your own words makes your thinking easier to revisit.'},
    {title:'Check again later',text:'Add a follow-up task to your planner. Return to the underlying idea before retaking a question. If you remember only the position of an answer, explain why the alternatives do not fit.'}
  ],activity:'Use one missed practice question. In your notes, complete: “I chose __ because __. The important distinction is __. My next review will focus on __.”'},
  {id:'midwifery-respect',track:'midwifery',title:'Recognise respectful care',minutes:5,summary:'Study dignity, privacy, informed choice, and support as connected ideas.',sources:['respect'],sections:[
    {title:'Experience is part of care',text:'WHO describes respectful care as protecting dignity and confidentiality, respecting rights, avoiding mistreatment, and supporting informed choices. The person’s experience matters alongside the provision of care.'},
    {title:'Look at the interaction',text:'In a learning scenario, notice whether communication invites questions and acknowledges the person’s preferences. Explaining a plan is different from assuming agreement. Follow your professional training and local consent requirements in practice.'},
    {title:'Reflect without identifiers',text:'Use a fictional or fully de-identified scenario in study notes. Name the communication issue and the principle it illustrates. Do not put patient names or other identifying details into this learning workspace.'}
  ],activity:'Write a fictional two-line interaction that invites a question and acknowledges a preference. Identify which respectful-care principle each line supports.'},
  {id:'midwifery-compare',track:'midwifery',title:'Compare ideas with a study matrix',minutes:6,summary:'Organise related concepts without turning them into rigid scripts.',sources:[],sections:[
    {title:'Choose a useful comparison',text:'Pick two related ideas from your approved midwifery learning materials. Put one on each side of a page. Use the same headings for both so differences become easier to inspect.'},
    {title:'Add context and uncertainty',text:'Suggested headings are purpose, information needed, explanation in my own words, and source. Add a row called “What would change the interpretation?” A comparison table is a revision tool, not a replacement for clinical judgement.'},
    {title:'Test the distinction',text:'Hide the table and explain one difference aloud or in writing. Reopen the source to check. Mark uncertainties as questions to bring to your tutor rather than filling gaps with guesses.'}
  ],activity:'Create a four-row comparison in your notes. Add one question you would like to discuss with your educator, then schedule a review.'},
  {id:'midwifery-reflect',track:'midwifery',title:'Build a reflective learning note',minutes:5,summary:'Move from “I studied” to a clear account of what you learned.',sources:[],sections:[
    {title:'Describe the learning task',text:'Name the topic and the resource you used. Keep the description brief. Reflection is more useful when you leave space to explain your thinking rather than recounting every step.'},
    {title:'Identify the change',text:'Write what you understood before, what you understand now, and what remains uncertain. Use fictional scenarios when helpful, and keep patient-identifying information out of your study records.'},
    {title:'Choose a next action',text:'A reflection can end with a practical study task: reread a section, discuss a question with your tutor, or revisit a concept. Add that action to the planner with a date you can realistically keep.'}
  ],activity:'Write three sentences beginning “Before this session…”, “Now I can explain…”, and “Next I will…”. Save the note and add the next action to your plan.'},
  {id:'public-health-promotion',track:'public-health',title:'Think beyond a health message',minutes:5,summary:'Recognise the difference between information and broader health promotion.',sources:['promotion'],sections:[
    {title:'Look beyond the leaflet',text:'WHO frames health promotion around helping people gain more influence over health. It includes personal knowledge and skills, but also policies, environments, and community participation.'},
    {title:'Ask what makes action possible',text:'In a study scenario, distinguish the message from the conditions for acting on it. A clear explanation may help, while transport, opening hours, language, or affordability can still create barriers.'},
    {title:'Map one learning example',text:'Choose a fictional community project. Write down the intended audience, what they want to achieve, one possible barrier, and one way you would learn more about that barrier before proposing a response.'}
  ],activity:'Make a two-column note: “What people need to know” and “What needs to be easier to do”. Add one fictional example to each column.'},
  {id:'public-health-literacy',track:'public-health',title:'Make information easier to use',minutes:5,summary:'Review a message for clarity, access, and a practical next step.',sources:['literacy'],sections:[
    {title:'Access is only the start',text:'WHO connects health literacy with finding, understanding, evaluating, and using information and services. A message being available does not mean it is understandable or usable.'},
    {title:'Review the learning example',text:'Choose a short fictional announcement. Identify its intended reader, its main point, and the action it asks for. Replace unnecessary jargon and make the next step specific. Ask someone from the intended audience what is unclear rather than assuming.'},
    {title:'Keep the scope honest',text:'This activity practises communication review. It does not authorise changing clinical instructions. Check factual statements against approved material and keep the original meaning intact.'}
  ],activity:'Rewrite this fictional study-group notice in plain language: “Participants should operationalise revision objectives prior to attendance.” Add a clear action and time.'},
  {id:'public-health-evaluate',track:'public-health',title:'Measure the learning you intended',minutes:6,summary:'Choose a useful indicator instead of relying on activity counts alone.',sources:[],sections:[
    {title:'Begin with the purpose',text:'For a fictional education project, write one intended change. Then choose a simple question that would help you understand whether that change happened. Keep the question aligned with the goal.'},
    {title:'Distinguish activity from learning',text:'The number of leaflets handed out describes an activity. It does not, by itself, show what people understood or whether access improved. List what each possible indicator can and cannot tell you.'},
    {title:'Plan a proportionate review',text:'Use a small, fictional example to practise. Think about whom you would ask, when, and how you would avoid collecting unnecessary personal information. Real projects require the appropriate supervision and permissions.'}
  ],activity:'For a fictional study workshop, write one activity measure and one learning question. Explain why they answer different questions.'}
];
export const PRACTICE_QUESTIONS=[
  {id:'q-map',track:'nclex',lesson:'nclex-plan',question:'Which resource is the best starting point for organising NCLEX-RN content revision?',options:['The current official NCSBN test plan','A list of recalled exam questions','A social-media prediction of likely topics','Only the last topic you studied'],answer:0,rationale:'The official plan describes the examination framework. Predictions and recalled content cannot establish the current outline. Use this starter alongside your approved learning materials.',sources:['nclex']},
  {id:'q-goal',track:'nclex',lesson:'nclex-plan',question:'Which study goal gives you the clearest way to check your learning?',options:['Read everything before bedtime','Spend a long time on a topic','Explain one named concept from memory, then check the source','Highlight as many pages as possible'],answer:2,rationale:'A specific explanation gives you something to check against the source. Time spent and pages highlighted describe activity without showing what you understood.',sources:[]},
  {id:'q-hygiene-before',track:'nclex',lesson:'nclex-hygiene',question:'In WHO’s framework, an aseptic task signals which hand-hygiene opportunity?',options:['Only at the end of the shift','Immediately before that task','Only after leaving the room','Only when contact is prolonged'],answer:1,rationale:'The framework includes preparation for aseptic work as a “before” opportunity. The other options postpone or restrict that opportunity incorrectly.',sources:['hygiene2']},
  {id:'q-hygiene-area',track:'nclex',lesson:'nclex-hygiene',question:'Does handling the area around a patient appear in the five-moments framework?',options:['No, only direct contact counts','Only in a theatre','Only if equipment looks dirty','Yes, it is one of the “after” opportunities'],answer:3,rationale:'The framework also considers contact with the surrounding care area. Direct contact is not its only focus. Use approved local procedures for practice.',sources:['hygiene2']},
  {id:'q-respect',track:'midwifery',lesson:'midwifery-respect',question:'Which interaction best supports informed participation?',options:['Assume silence means agreement','Explain the plan and invite questions about preferences','Avoid explanations to save time','Discuss personal information where everyone can hear'],answer:1,rationale:'Explanation and an invitation to ask questions support participation. Assumptions, withheld information, and public disclosure undermine the principles in this example.',sources:['respect2']},
  {id:'q-privacy',track:'midwifery',lesson:'midwifery-respect',question:'What belongs in a personal study reflection?',options:['A patient’s full name and ward location','An identifiable screenshot of a care record','A fictional or fully de-identified learning example','A list of private contact details'],answer:2,rationale:'A learning reflection can focus on the principle without identifying a person. The other options introduce unnecessary personal information.',sources:[]},
  {id:'q-compare',track:'midwifery',lesson:'midwifery-compare',question:'A comparison table leaves you uncertain about a distinction. What is the best study response?',options:['Record the uncertainty and check an approved source or tutor','Fill the gap with an online guess','Delete the uncertain row','Treat the table as a clinical protocol'],answer:0,rationale:'Writing down the uncertainty makes it actionable. A study table organises understanding; it does not replace an authoritative source or supervised clinical judgement.',sources:[]},
  {id:'q-reflect',track:'midwifery',lesson:'midwifery-reflect',question:'Which ending makes a reflection most actionable?',options:['“I spent an hour studying.”','“This topic felt difficult.”','“I copied all the notes.”','“Tomorrow I will revisit this named concept and explain it in my own words.”'],answer:3,rationale:'The final option names a topic, a time, and a way to review it. The other statements may describe an experience but do not specify the next action.',sources:[]},
  {id:'q-promotion',track:'public-health',lesson:'public-health-promotion',question:'Which description best fits a broad health-promotion approach?',options:['Distribute a message and ignore access barriers','Consider information, enabling conditions, and community participation','Measure success only by printing more leaflets','Assume everyone has the same opportunities'],answer:1,rationale:'The approach includes more than information alone. Conditions that make action possible and community involvement also matter.',sources:['promotion']},
  {id:'q-literacy',track:'public-health',lesson:'public-health-literacy',question:'A leaflet is available online but readers cannot understand its language. What is the key lesson?',options:['Availability guarantees usability','Longer wording always improves understanding','Access alone does not ensure information can be understood and used','The audience should not be involved in review'],answer:2,rationale:'Health literacy concerns more than availability. Understanding and practical use matter too; audience feedback can reveal a communication barrier.',sources:['literacy']},
  {id:'q-evaluate',track:'public-health',lesson:'public-health-evaluate',question:'“We handed out 200 leaflets” tells you most directly about what?',options:['An activity completed','A proven improvement in health','Everyone’s understanding','A guaranteed change in access'],answer:0,rationale:'A distribution count measures activity. Additional, appropriately chosen information is needed to understand learning, access, or outcomes.',sources:[]},
  {id:'q-review',track:'public-health',lesson:'public-health-evaluate',question:'What should you do first when choosing a measure for a fictional learning project?',options:['Copy the largest number used elsewhere','Collect every possible personal detail','Pick the easiest statistic regardless of purpose','State the intended change and choose a measure that relates to it'],answer:3,rationale:'A measure is more useful when it relates to the purpose. Convenience or a large number does not, by itself, establish relevance.',sources:[]}
];
